BEGIN;
CREATE TABLE IF NOT EXISTS paises (pai_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,pai_cod VARCHAR(10) NOT NULL,pai_nom VARCHAR(100) NOT NULL,pai_usu_mov VARCHAR(50) NOT NULL,pai_fec_mov TIMESTAMP NOT NULL,pai_act BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(cli_id,pai_cod));
CREATE TABLE IF NOT EXISTS provincias (prv_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,pai_id BIGINT NOT NULL,prv_cod VARCHAR(10) NOT NULL,prv_nom VARCHAR(100) NOT NULL,prv_usu_mov VARCHAR(50) NOT NULL,prv_fec_mov TIMESTAMP NOT NULL,prv_act BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(cli_id,prv_cod),FOREIGN KEY(pai_id) REFERENCES paises(pai_id));
CREATE TABLE IF NOT EXISTS municipios (mun_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,prv_id BIGINT NOT NULL,mun_cod VARCHAR(20) NOT NULL,mun_nom VARCHAR(100) NOT NULL,mun_usu_mov VARCHAR(50) NOT NULL,mun_fec_mov TIMESTAMP NOT NULL,mun_act BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(cli_id,mun_cod),FOREIGN KEY(prv_id) REFERENCES provincias(prv_id));
CREATE TABLE IF NOT EXISTS codigos_postales (cop_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,mun_id BIGINT NOT NULL,cop_cod VARCHAR(10) NOT NULL,cop_usu_mov VARCHAR(50) NOT NULL,cop_fec_mov TIMESTAMP NOT NULL,cop_act BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(cli_id,cop_cod),FOREIGN KEY(mun_id) REFERENCES municipios(mun_id));
CREATE TABLE IF NOT EXISTS vias (via_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,cop_id BIGINT NOT NULL,via_tip VARCHAR(30) NOT NULL,via_cod VARCHAR(30) NOT NULL,via_nom VARCHAR(150) NOT NULL,via_usu_mov VARCHAR(50) NOT NULL,via_fec_mov TIMESTAMP NOT NULL,via_act BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(cli_id,via_cod),FOREIGN KEY(cop_id) REFERENCES codigos_postales(cop_id),CHECK(via_tip IN ('Calle','Avenida','Plaza','Paseo','Camino','Carretera','Travesía','Urbanización','Polígono','Otro')));
CREATE INDEX IF NOT EXISTS idx_provincias_cli_pai ON provincias(cli_id,pai_id); CREATE INDEX IF NOT EXISTS idx_municipios_cli_prv ON municipios(cli_id,prv_id); CREATE INDEX IF NOT EXISTS idx_codigos_cli_mun ON codigos_postales(cli_id,mun_id); CREATE INDEX IF NOT EXISTS idx_vias_cli_cop ON vias(cli_id,cop_id);
ALTER TABLE domicilios ADD COLUMN IF NOT EXISTS dom_via_id BIGINT;
CREATE INDEX IF NOT EXISTS idx_domicilios_cli_via ON domicilios(cli_id,dom_via_id);
COMMIT;
